L5_1 = "상태이상 저항이 40% 증가한다. 전장을 주술의 힘으로 둘러싼다. 시전자가 생존해 있는 동안 모든 적 유닛은 받는 회복량이 90% 감소한다. 건틀렛에서는 받는 회복량 감소 효과가 회복 불가로 변경된다. 또한, 영구적으로 적 레인저, 스트라이커, 스나이퍼 유닛의 공격속도가 15% 감소하고 동일한 대상의 스킬충전속도가 12초간 75% 감소한다(해제불가)."
